def run_plan(plan, world, llm):
    for action in plan:
        predicted = world.predict(action)              # consequences before execution
        problem = world.violation(action, predicted)   # unmet precondition, wrong object
        if problem is None:
            world.execute(action)
        elif world.can_repair(problem):
            world.execute(world.repair(action, problem))   # fix follows from the graph
        else:
            new_plan = llm.replan(world.state(), problem)  # only semantic errors reach the LLM
            return run_plan(new_plan, world, llm)
